import{baseFor,includedFor,normalizeExtras,normalizeTreatments,quoteFor,money,findService,findPlan}from'./catalog.mjs';
import{mountCarSurface}from'./car-surface.mjs';
const zones=[{id:'pintura',label:'Pintura'},{id:'vidros',label:'Vidros'},{id:'rodas',label:'Rodas'},{id:'interior',label:'Interior'},{id:'acabamentos',label:'Acabamentos'}];
const copy={geral:{label:'Visão geral',description:'O cuidado começa no conjunto.'},pintura:{label:'Pintura',description:'Brilho, correção e proteção da superfície.'},vidros:{label:'Vidros',description:'Limpeza técnica e proteção dos vidros externos.'},rodas:{label:'Rodas',description:'Limpeza e descontaminação das rodas.'},interior:{label:'Interior',description:'Bancos, carpetes e acabamentos internos.'},acabamentos:{label:'Acabamentos',description:'Tratamento dos plásticos externos compatíveis.'}};
const views=[['geral','Carro'],['pintura','Pintura'],['interior','Interior'],['rodas','Rodas'],['vidros','Vidros']];const mounted=new WeakMap();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function areaForCare(id){if(['polishLight','polishMedium','polishPremium','coating','paintIron','wax'].includes(id))return'pintura';if(['fullClean','leather','fabric','carpet','interiorPlastic'].includes(id))return'interior';if(id==='wheelIron')return'rodas';if(id==='glassCare')return'vidros';if(['exteriorPlastic','plasticCoating'].includes(id))return'acabamentos';return null;}
export function zonesForCare(s){if(s.vehicle!=='car')return[];const base=baseFor(s),active=new Set();if(['essential','premium','extra'].includes(base))['pintura','vidros','rodas','interior'].forEach(x=>active.add(x));if(base==='extra')active.add('acabamentos');for(const id of[base,...includedFor(s),...normalizeExtras(s),...normalizeTreatments(s)]){const z=areaForCare(id);if(z)active.add(z);}if(s.mode==='guidance')for(const goal of s.goals||[]){const z={Pintura:'pintura',Interior:'interior',Rodas:'rodas',Acabamentos:'acabamentos'}[goal];if(z)active.add(z);}return zones.filter(z=>active.has(z.id)).map(z=>z.id);}
export function sceneForCare(s,focus=null){const active=zonesForCare(s),scene=copy[focus]?focus:areaForCare(baseFor(s))||'geral',service=s.mode==='plan'?findPlan(s.plan):findService(baseFor(s)),q=quoteFor(s);return{active,scene,...copy[scene],service:service?.label||service?.name||'Seu cuidado',amount:q.items.length?money(q.total):'A combinar',recurring:!!q.recurring&&!q.additional};}
export function vehicleMapMarkup(s,{root='../',focus=null,compact=false}={}){if(s.vehicle!=='car')return'';const d=sceneForCare(s,focus);return '<section class="visual-care-map ffv-vehicle '+(compact?'visual-care-mobile':'')+'" data-scene="'+d.scene+'" aria-label="Visualização do cuidado no veículo"><div class="ffv-vehicle-top"><span>Seu carro, em foco</span><span class="ffv-view-label" data-view-label>'+d.label+'</span></div><div class="ffv-vehicle-canvas" role="img" aria-label="'+esc(d.label+'. '+d.description)+'"><div class="fn-car-host" data-car-surface><img class="fn-car-fallback" src="'+root+'assets/car-preview.webp" alt="Cupê prateado" width="800" height="500"></div><span class="fn-drag-note">Arraste para girar</span></div><div class="ffv-view-options" role="group" aria-label="Ver as áreas do carro de perto">'+views.map(([id,label])=>'<button type="button" data-vehicle-focus="'+id+'" aria-pressed="'+(id===d.scene)+'">'+label+'</button>').join('')+'</div><div class="ffv-vehicle-caption"><p data-view-description>'+d.description+'</p></div><div class="ffv-live-selection" aria-live="polite" aria-atomic="true"><div><span>Cuidado escolhido</span><strong data-view-service>'+esc(d.service)+'</strong></div><div><strong data-view-amount>'+d.amount+'</strong><span data-view-period>'+(d.recurring?'/ mês':'valor estimado')+'</span></div></div></section>';}
export function updateVehicleMap(element,s,options={}){if(!element||s.vehicle!=='car')return;const d=sceneForCare(s,options.focus),old=mounted.get(element);let viewer=old?.viewer;const current={selection:s,options,viewer};mounted.set(element,current);element.dataset.scene=d.scene;for(const[k,v]of Object.entries({'label':d.label,'description':d.description,'service':d.service,'amount':d.amount,'period':d.recurring?'/ mês':'valor estimado'}))element.querySelector('[data-view-'+k+']').textContent=v;element.querySelector('.ffv-vehicle-canvas').setAttribute('aria-label',d.label+'. '+d.description);element.querySelectorAll('[data-vehicle-focus]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.vehicleFocus===d.scene)));if(!old){element.addEventListener('click',e=>{const b=e.target.closest('[data-vehicle-focus]');if(!b)return;const c=mounted.get(element);updateVehicleMap(element,c.selection,{...c.options,focus:b.dataset.vehicleFocus});});element.addEventListener('car-view-change',()=>{const c=mounted.get(element);updateVehicleMap(element,c.selection,{...c.options,focus:'geral'});});if(globalThis.document&&element.isConnected){viewer=mountCarSurface(element.querySelector('[data-car-surface]'),{root:options.root,view:d.scene});current.viewer=viewer;}}viewer?.setView(d.scene);return element;}
export function mountVehicleMap(host,s,options={}){if(!host)return;if(s.vehicle!=='car'){host.innerHTML='';return;}let e=host.matches('.ffv-vehicle')?host:host.querySelector('.ffv-vehicle');if(!e){host.innerHTML=vehicleMapMarkup(s,options);e=host.querySelector('.ffv-vehicle');}return updateVehicleMap(e,s,options);}
